// Adds a team guess from the job title and keeps the columns we want in the sheet.
const TEAMS = [
  ['Leadership', /\b(head of|director|vp|vice president|chief|country manager|general manager)\b/i],
  ['Recruiting & People', /recruit|sourcer|talent|people partner|\bhr\b/i],
  ['Sales', /sales|account executive|account manager|business development|\b[bs]dr\b|partnership/i],
  ['Marketing', /marketing|growth|brand|content|communications/i],
  ['Customer', /support|success|customer|solutions|implementation/i],
  ['Data & AI', /\bdata\b|machine learning|\bml\b|\bai\b|research|scientist|analytics/i],
  ['Engineering', /engineer|developer|software|backend|frontend|full.?stack|\bsre\b|devops|infrastructure|security/i],
  ['Product & Design', /product|design|\bux\b|\bui\b/i],
];
const teamOf = title => (TEAMS.find(([, re]) => re.test(title)) || ['Other'])[0];

return $input.all().map(i => {
  const j = i.json;
  return { json: {
    found_at: $now.toFormat('yyyy-MM-dd'),
    company: j.company,
    team: teamOf(j.title || ''),
    title: j.title,
    location: j.location,
    remote: j.remote ? 'yes' : 'no',
    posted_at: String(j.postedAt || '').slice(0, 10),
    url: j.url,
    source: j.source,
  } };
});

// One Slack message: new roles per company, with a team breakdown and the first few titles.
const SHOW_TITLES = 5;
const jobs = $input.all().map(i => i.json);
if (jobs.length === 0) return [];

const byCompany = {};
for (const j of jobs) (byCompany[j.company] = byCompany[j.company] || []).push(j);

const esc = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\|/g, '-').trim();
const companies = Object.entries(byCompany).sort((a, b) => b[1].length - a[1].length);
let text = `*Hiring signals*: ${jobs.length} new role(s) at ${companies.length} company(ies)\n`;
for (const [company, list] of companies) {
  const teams = {};
  for (const j of list) teams[j.team] = (teams[j.team] || 0) + 1;
  const mix = Object.entries(teams).sort((a, b) => b[1] - a[1]).map(([t, n]) => `${t} ${n}`).join(', ');
  text += `\n*${esc(company)}*: ${list.length} new (${mix})\n`;
  for (const j of list.slice(0, SHOW_TITLES)) text += `- <${j.url}|${esc(j.title)}> - ${esc(j.location)}\n`;
  if (list.length > SHOW_TITLES) text += `...and ${list.length - SHOW_TITLES} more (see the sheet)\n`;
}
return [{ json: { text } }];
